#!/usr/bin/env python3
"""Build an evidence-backed semantic slice for geospatial analytics."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
SEM = HERE.parent
REGISTRY = SEM.parents[1]
AS_OF = "2026-08-27"
AXES = ["semantic_object","semantic_role","identity_and_equality","grain_and_cardinality","state_and_change","time","order_and_topology","partiality_and_uncertainty","authority_and_trust","effect_boundary","representation","composition_algebra","compatibility_and_evolution","resources_and_failure","evidence_and_conformance","privacy_security_safety"]


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def canonical(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def slug(value: str) -> str:
    return value.replace("_", "-").replace(".", "-")


def library_universe() -> list[str]:
    rows = load_jsonl(REGISTRY / "library-contributions.jsonl")
    exact = {
        "library.method_kernels.coordinate_transform_methods", "library.method_kernels.raster_grid_methods",
        "library.method_kernels.spatial_methods", "library.method_kernels.spatial_reference_semantics",
        "library.method_kernels.spatial_statistics_methods", "library.method_kernels.vector_geometry_topology",
        "library.predictive.spatial_models", "library.qck.spatial-kernels", "library.qck.spatial-semantics",
    }
    prefixes = ("library.geocode.", "library.pointcloud.", "library.spatial_", "library.terrain.", "library.trajectory.")
    return sorted(row["library_id"] for row in rows if row["library_id"] in exact or row["library_id"].startswith(prefixes))


LIBRARIES = library_universe()


def sources() -> list[dict[str, Any]]:
    rows = [
        ("feature-model","OGC Abstract Specification Topic 5 — Features",["Open Geospatial Consortium"],2026,"normative_geospatial_model","https://docs.ogc.org/as/17-087r13/17-087r13.html","Separates geographic features and their properties from geometric representations.","Feature semantics remain application-domain owned."),
        ("simple-features","Simple Feature Access — Part 1: Common Architecture",["Open Geospatial Consortium"],2011,"normative_geometry_standard","https://www.ogc.org/standards/sfa/","Defines a simple-feature geometry model, coordinate dimension and spatial relations.","The simple linear geometry profile is not all geographic reality, topology, coverage or 3D semantics."),
        ("iso19111","ISO 19111:2019 Geographic information — Referencing by coordinates",["ISO/TC 211"],2019,"international_standard","https://www.iso.org/standard/74039.html","Defines coordinate reference systems, datums, coordinate operations and coordinate epochs.","A CRS identifier alone does not supply transformation accuracy or domain fitness."),
        ("wkt-crs","Well-known text representation of coordinate reference systems",["Open Geospatial Consortium","ISO/TC 211"],2019,"normative_encoding_standard","https://docs.ogc.org/is/18-010r7/18-010r7.html","Provides an editioned carrier for CRS and coordinate-operation definitions.","WKT parseability is not CRS equivalence or transformation correctness."),
        ("epsg","EPSG Geodetic Parameter Dataset",["IOGP"],2026,"authoritative_parameter_registry","https://epsg.org/","Publishes identifiers and parameters for CRSs, datums and coordinate operations.","Registry entries do not select the correct CRS or operation for a use case."),
        ("proj","PROJ coordinate transformation software",["PROJ contributors"],2026,"official_provider_contract","https://proj.org/","Implements CRS parsing and coordinate-operation pipelines with area-of-use and accuracy metadata.","A provider-selected pipeline is not semantic authority and grid availability affects results."),
        ("geojson","RFC 7946 — The GeoJSON Format",["IETF"],2016,"internet_standard","https://www.rfc-editor.org/rfc/rfc7946","Defines Feature, FeatureCollection and geometry JSON carriers in WGS 84 longitude/latitude.","GeoJSON lines are Cartesian in the declared CRS and may differ from geodesics; the carrier is not feature truth."),
        ("features-json","OGC Features and Geometries JSON — Part 1: Core",["Open Geospatial Consortium"],2026,"normative_current_encoding","https://docs.ogc.org/is/21-045r1/21-045r1.html","Extends JSON feature/geometry encoding with explicit CRS, dimensions and measures.","Encoding expressiveness does not establish geometry validity, accuracy or analytical fitness."),
        ("geosparql","OGC GeoSPARQL 1.1",["Open Geospatial Consortium"],2024,"normative_query_ontology","https://docs.ogc.org/is/22-047r1/22-047r1.html","Separates spatial features, geometries, serializations, topological relations, functions and query rewriting with conformance classes.","RDF entailment or a computed relation does not establish domain-feature identity."),
        ("geoparquet","GeoParquet 1.1.0",["GeoParquet project"],2025,"community_encoding_specification","https://geoparquet.org/releases/v1.1.0/","Defines columnar geometry encoding and geospatial metadata for Parquet.","Columnar transport and bounding metadata do not define all topology, feature or CRS semantics."),
        ("coverage","OGC Coverage Implementation Schema 1.1",["Open Geospatial Consortium"],2019,"normative_coverage_standard","https://docs.ogc.org/is/09-146r8/09-146r8.html","Separates coverage domain set, range set, range type and encoding across grids, point clouds and meshes.","Raster imagery is only one coverage representation and some encodings are informationally incomplete."),
        ("cog","OGC Cloud Optimized GeoTIFF 1.0",["Open Geospatial Consortium"],2023,"normative_cloud_encoding","https://docs.ogc.org/is/21-026/21-026.html","Defines tiled, reduced-resolution, georeferenced TIFF plus HTTP range requirements for partial access.","COG optimizes access; it does not add source resolution or semantic accuracy."),
        ("stac","SpatioTemporal Asset Catalog Specification",["STAC community"],2026,"community_catalog_specification","https://stacspec.org/en/about/stac-spec/","Separates atomic Item, asset links, Catalog and Collection metadata.","A STAC Item is descriptive metadata and links, not the asset bytes, observation truth or quality proof."),
        ("om","OGC/ISO Observations, Measurements and Samples",["Open Geospatial Consortium","ISO/TC 211"],2023,"normative_observation_model","https://www.ogc.org/standards/om/","Separates observation, feature of interest, observed property, procedure, result, sampling and phenomenon time.","An observation result is not the feature or phenomenon itself."),
        ("iso19157","ISO 19157-1:2023 Geographic information — Data quality",["ISO/TC 211"],2023,"international_quality_standard","https://www.iso.org/standard/78900.html","Defines quality principles, components and evaluation for geographic data.","A quality element or score is scoped to data, measure and evaluation procedure, not universal fitness."),
        ("asprs-accuracy","ASPRS Positional Accuracy Standards for Digital Geospatial Data, Edition 2",["ASPRS"],2024,"professional_standard","https://www.asprs.org/divisions-committees/standards","Defines current horizontal and vertical positional-accuracy reporting and checkpoints.","Positional accuracy does not establish thematic, temporal, completeness or decision fitness."),
        ("qgis-processing","QGIS Processing framework documentation",["QGIS project"],2026,"official_workbench_provider_contract","https://docs.qgis.org/latest/en/docs/user_manual/processing/","Defines projects, layers, processing algorithms, models, history, parameters, outputs and provider execution in an independently adopted GIS workbench.","QGIS project and processing behavior is provider evidence, not portable semantic ownership or implementation qualification."),
        ("gdal","GDAL documentation",["OSGeo GDAL project"],2026,"official_provider_contract","https://gdal.org/","Implements raster/vector access, translation, warping and many provider formats.","Driver availability does not prove lossless conversion or select resampling/CRS policy."),
        ("geos","GEOS documentation",["GEOS project"],2026,"official_provider_contract","https://libgeos.org/","Implements computational geometry and Simple Features predicates/operations.","Floating precision, validity and repair semantics remain explicit provider concerns."),
        ("postgis","PostGIS Reference",["PostGIS project"],2026,"official_provider_contract","https://postgis.net/docs/reference.html","Implements geometry/geography types, indexes, predicates, measurement and transformation in PostgreSQL.","A database extension is not the semantic owner or a full analytical workbench."),
        ("pysal-esda","PySAL Exploratory Spatial Data Analysis",["PySAL project"],2026,"official_method_provider","https://pysal.org/esda/","Implements spatial autocorrelation and exploratory statistics over declared spatial weights.","A clustering statistic does not establish cause, mechanism or universal neighborhood meaning."),
        ("pysal-spreg","PySAL Spatial Regression",["PySAL project"],2026,"official_method_provider","https://pysal.org/spreg/","Implements spatial lag, error and related regression families.","Provider fitting does not validate weights, sampling, stationarity or causal interpretation."),
        ("iso19160","ISO 19160-1:2015 Addressing — Conceptual model",["ISO/TC 211"],2015,"international_address_standard","https://www.iso.org/standard/61710.html","Defines address components and lifecycle concepts independently of coordinate geometry.","An address is not a coordinate, place identity or proof of occupancy."),
        ("nominatim","Nominatim documentation",["OpenStreetMap Nominatim project"],2026,"official_provider_contract","https://nominatim.org/release-docs/latest/","Implements search/reverse-geocoding over an indexed gazetteer with ranking and result metadata.","A match is provider- and data-edition scoped and not authoritative place identity."),
        ("routes","OGC API — Routes",["Open Geospatial Consortium"],2026,"normative_api_standard","https://ogcapi.ogc.org/routes/overview.html","Separates route requests, profiles, results, asynchronous jobs and route exchange from underlying engines.","A computed route is not an authorized itinerary, dispatch or safety guarantee."),
        ("moving-features","OGC Moving Features Encoding Extension — JSON",["Open Geospatial Consortium"],2020,"normative_trajectory_encoding","https://docs.ogc.org/is/19-045r3/19-045r3.html","Represents moving-feature trajectories, temporal geometry/properties, CRS and temporal reference systems.","Encoded samples or interpolated trajectories are not complete actual movement."),
        ("mobilitydb","MobilityDB documentation",["MobilityDB project"],2026,"official_provider_contract","https://docs.mobilitydb.com/","Implements temporal and spatiotemporal database types and operations.","Database trajectory operations do not own moving-object identity or map-matching truth."),
        ("grass-watershed","GRASS GIS r.watershed",["GRASS GIS project"],2026,"official_method_provider","https://grass.osgeo.org/grass-stable/manuals/r.watershed.html","Implements watershed, flow accumulation and drainage derivation from elevation rasters.","Derived drainage depends on elevation datum, resolution, preprocessing and flow algorithm."),
        ("tarboton","A new method for the determination of flow directions and upslope areas in grid digital elevation models",["David G. Tarboton"],1997,"peer_reviewed_primary_method","https://doi.org/10.1029/96WR03137","Defines D-infinity flow direction on gridded elevation surfaces.","A flow algorithm is a model choice and does not turn a DEM into terrain truth."),
        ("las","ASPRS LAS Specification",["ASPRS LAS Working Group"],2025,"professional_encoding_standard","https://github.com/ASPRSorg/LAS","Defines point records, attributes, classifications, CRS metadata and file editions for lidar point clouds.","Point classification codes and returns do not establish physical-object identity or analytical accuracy."),
        ("copc","Cloud Optimized Point Cloud Specification",["COPC project"],2021,"community_encoding_specification","https://copc.io/","Defines a range-readable octree organization within LAZ for cloud-native point access.","COPC changes access organization, not source precision, classification truth or semantic ownership."),
        ("3dtiles","OGC 3D Tiles 1.1",["Open Geospatial Consortium","Cesium"],2022,"community_standard","https://www.ogc.org/standards/3dtiles/","Defines hierarchical tilesets and formats for streaming 3D models, buildings, meshes and point clouds.","A level of detail or tile transform does not preserve every measurement or analytical claim."),
        ("pdal","PDAL documentation",["PDAL project"],2026,"official_provider_contract","https://pdal.io/en/stable/","Implements point-cloud readers, filters, writers, pipelines, metadata and spatial references.","A PDAL stage name does not qualify algorithm semantics or result fitness."),
        ("openeo","openEO API 1.2",["openEO project"],2024,"open_processing_protocol","https://api.openeo.org/1.2/","Defines process graphs, data-cube processing, batch jobs, results and user-defined processes.","A remotely executable process graph does not qualify each operator or guarantee cross-provider equivalence."),
        ("ogc-processes","OGC API — Processes — Part 1: Core",["Open Geospatial Consortium"],2021,"normative_processing_api","https://docs.ogc.org/is/18-062r2/18-062r2.html","Defines process descriptions, inputs, outputs, synchronous/asynchronous execution and job resources.","An API process identifier is not a portable semantic operation contract."),
        ("cwl","Common Workflow Language v1.2",["CWL Project"],2020,"normative_workflow_specification","https://www.commonwl.org/v1.2/","Defines typed workflow inputs, outputs, steps, requirements, hints and provenance-oriented execution.","Generic workflow types do not preserve CRS, spatial support or algorithm loss unless declared."),
        ("prov","W3C PROV-O",["World Wide Web Consortium"],2013,"web_recommendation","https://www.w3.org/TR/prov-o/","Defines entity, activity, agent, generation, use, derivation and attribution relations.","Provenance records do not prove correctness, causality or spatial accuracy."),
        ("records","OGC API — Records — Part 1: Core",["Open Geospatial Consortium"],2025,"normative_catalog_api","https://docs.ogc.org/is/20-004r1/20-004r1.html","Defines records, catalogs, browsing, search and resource links.","A discoverable record is not the resource, its authority or its quality proof."),
        ("dggs","OGC API — Discrete Global Grid Systems — Part 1: Core",["Open Geospatial Consortium"],2025,"normative_current_api","https://docs.ogc.org/is/21-038r1/21-038r1.html","Defines API access to data organized by discrete global grid reference systems.","A DGGS zone identifier is not interchangeable with geometry, feature identity or every analysis support."),
        ("geoxacml","OGC GeoXACML 3.0",["Open Geospatial Consortium"],2023,"normative_spatial_policy_standard","https://docs.ogc.org/is/22-049r1/22-049r1.html","Extends policy evaluation with geometry, CRS and topological functions plus typed errors.","Spatial policy predicates do not establish location truth or effect authority by themselves."),
    ]
    return [{"source_id":f"source.geospatial.{sid}","title":title,"authors_or_publisher":authors,"year":year,"source_kind":kind,"url":url,"bounded_implication":imp,"authority_limit":limit} for sid,title,authors,year,kind,url,imp,limit in rows]


