def build() -> dict[str, Any]:
    src,mods,law,method,expert,innovation=sources(),modules(),laws(),methods(),experts(),innovations()
    contributions={x["library_id"]:x for x in load_jsonl(REGISTRY/"library-contributions.jsonl")}
    coord={x["library_ref"]:x for x in load_jsonl(SEM/"library_coordinate_binding_projection/library-coordinate-binding-dockets.jsonl")}
    exact={x["library_ref"]:x for x in load_jsonl(SEM/"p5_exact_contract_adjudication/exact-contract-dockets.jsonl")}
    products={x:set() for x in LIBRARIES};subjects={x:set() for x in LIBRARIES}
    for s in load_jsonl(SEM/"product_coordinate_binding_projection/subject-coordinate-binding-projections.jsonl"):
        for edge in s["concrete_bindings"]:
            ref=edge["concrete_library_ref"]
            if ref in products: products[ref].add(s["product_ref"]);subjects[ref].add(s["subject_ref"])
    targeted={(x["axis"],x["library_ref"]):x for x in load_jsonl(SEM/"targeted_evidence_cluster_adjudication/member-adjudication-occurrences.jsonl")}
    bymod={x["module_id"]:x for x in mods};librows=[];axisrows=[]
    for ref in LIBRARIES:
        m=[f"module.geospatial.{x}" for x in MODULE_MAP[ref]]; evidence=sorted({s for x in m for s in bymod[x]["source_refs"]})
        if ref=="library.method_kernels.spatial_methods": disposition="COMPOSITION_FACADE_ONLY_NO_SEMANTIC_OWNERSHIP"
        elif ref.startswith("library.qck."): disposition="MOVE_TO_QUERY_ENGINE_SPATIAL_ACL"
        elif ref=="library.predictive.spatial_models": disposition="RETAIN_PREDICTIVE_BOUNDARY_IMPORT_SPATIAL_SEMANTICS"
        else: disposition="RETAIN_NARROW_MODULE_BOUNDARY"
        librows.append({"record_kind":"geospatial_analytics_library_semantic_binding_candidate","binding_id":f"binding.geospatial-semantic-slice.{slug(ref)}.v1","library_ref":ref,"library_name":contributions[ref]["name"],"semantic_module_refs":m,"evidence_refs":evidence,"exact_contract_docket_ref":exact[ref]["docket_id"],"coordinate_binding_docket_ref":coord[ref]["binding_docket_id"],"downstream_subject_refs":sorted(subjects[ref]),"downstream_product_refs":sorted(products[ref]),"boundary_disposition_candidate":disposition,"compiler_binding":"REFUSED","refusal_reasons":["OWNER_RATIFICATION_MISSING","MEMBER_AXIS_APPLICABILITY_UNRATIFIED","EXACT_CONTRACT_UNSELECTED","IMPLEMENTATIONS_UNQUALIFIED"],"completion_claim":False})
        for axis in AXES:
            t=targeted.get((axis,ref));axisrows.append({"record_kind":"geospatial_analytics_library_axis_decision_candidate","decision_candidate_id":f"decision-candidate.geospatial-axis.{slug(ref)}.{axis.replace('_','-')}.v1","library_ref":ref,"axis":axis,"semantic_module_refs":m,"coordinate_question":AXIS_QUESTIONS[axis],"applicability_candidate":"REQUIRED_EXPLICIT_PROFILE","evidence_refs":evidence,"targeted_member_adjudication_occurrence_ref":t["occurrence_id"] if t else None,"coordinate_answers":[],"member_applicability":"PROPOSED_OWNER_REVIEW_REQUIRED","owner_decision":"UNRATIFIED","status":"EVIDENCE_BACKED_DECISION_QUESTION_NOT_ANSWER","canonical_gaps_closed":0,"completion_claim":False})
    findings=boundary_findings(products)
    context={"record_kind":"bounded_context_candidate","context_id":"context.geospatial-analytics-semantic-slice.v1","as_of":AS_OF,"vision":"How can phenomena, features, observations and positions be represented, transformed, analyzed and published across spatial supports without collapsing coordinates into locations, features into geometries, coverages into files, predictions into observations, proximity into reachability or maps into authority?","inside":["feature/observation/support/reference semantics","coordinate operations","vector geometry/topology","coverage/raster/grid/terrain","spatial statistics and uncertainty","geocoding/gazetteer resolution","network routing/accessibility","moving objects/trajectories","point clouds/3D/LOD","representation ACLs and catalog assets","project/layer/workflow/run lifecycle","accuracy appraisal/publication/recall"],"outside":["application-domain feature truth","generic query engine ownership","predictive model lifecycle","physical sensing/acquisition control","dispatch/navigation/action authority","generic storage/compute/orchestration","cartographic UI styling totality","LLM/agent orchestration"],"neighbors":[{"context_ref":"context.query-engine","relationship":"anti_corruption_layer"},{"context_ref":"context.predictive-analytics-semantic-slice","relationship":"anti_corruption_layer"},{"context_ref":"context.catalog-discovery","relationship":"published_language"},{"context_ref":"context.runtime-resource-control","relationship":"customer_supplier"},{"context_ref":"context.domain-decision-authority","relationship":"anti_corruption_layer"}],"published_language":["GeographicFeatureRef","SpatialObservation","SpatialSupport","CoordinateReferenceSystem","CoordinateOperation","Geometry","Coverage","RasterGrid","SpatialWeights","GeocodeCandidate","SpatialNetwork","RouteResult","Trajectory","PointCloud","SpatialAssetRef","SpatialWorkflowEdition","SpatialRunEvidence","SpatialAccuracyStatement","SpatialPublicationIntent"],"ratification":"WITHHELD","completion_claim":False}
    summary={"program_id":"program.geospatial-analytics-semantic-slice.v1","as_of":AS_OF,"primary_or_official_sources":len(src),"semantic_modules":len(mods),"non_collapse_laws":len(law),"method_types":len(method),"expert_learning_profiles":len(expert),"recent_non_llm_innovations":len(innovation),"bound_libraries":len(librows),"library_axis_decision_candidates":len(axisrows),"product_capability_boundary_findings":len(findings),"downstream_products":len({p for v in products.values() for p in v}),"libraries_without_declared_product_consumer":sum(not v for v in products.values()),"owner_decisions":0,"exact_contracts_selected":0,"qualified_implementations":0,"canonical_gaps_closed":0,"completion_claim":False}
    return {"context":context,"sources":src,"modules":mods,"laws":law,"methods":method,"experts":expert,"innovations":innovation,"libraries":librows,"axes":axisrows,"findings":findings,"summary":summary}


def outputs() -> dict[str,str]:
    b=build();files={"bounded-context.json":json.dumps(b["context"],ensure_ascii=False,sort_keys=True,indent=2)+"\n","primary-sources.jsonl":"".join(canonical(x)+"\n" for x in b["sources"]),"semantic-modules.jsonl":"".join(canonical(x)+"\n" for x in b["modules"]),"non-collapse-laws.jsonl":"".join(canonical(x)+"\n" for x in b["laws"]),"geospatial-method-taxonomy.jsonl":"".join(canonical(x)+"\n" for x in b["methods"]),"expert-learning-profiles.jsonl":"".join(canonical(x)+"\n" for x in b["experts"]),"innovation-records.jsonl":"".join(canonical(x)+"\n" for x in b["innovations"]),"library-semantic-bindings.jsonl":"".join(canonical(x)+"\n" for x in b["libraries"]),"library-axis-decision-candidates.jsonl":"".join(canonical(x)+"\n" for x in b["axes"]),"product-capability-boundary-findings.jsonl":"".join(canonical(x)+"\n" for x in b["findings"]),"summary.json":json.dumps(b["summary"],ensure_ascii=False,sort_keys=True,indent=2)+"\n"}
    claims={n:{"bytes":len(v.encode()),"sha256":hashlib.sha256(v.encode()).hexdigest()} for n,v in files.items()};files["manifest.json"]=json.dumps({"manifest_id":"manifest.geospatial-analytics-semantic-slice.v1","as_of":AS_OF,"files":claims,"completion_claim":False},sort_keys=True,indent=2)+"\n";return files


def main() -> int:
    for n,v in outputs().items():(HERE/n).write_text(v)
    s=build()["summary"];print(f"BUILD PASS geospatial analytics semantic slice: {s['semantic_modules']} modules, {s['method_types']} methods, {s['bound_libraries']} libraries and {s['library_axis_decision_candidates']} unresolved axis decisions");return 0


if __name__=="__main__":raise SystemExit(main())
